<?php if($overview!==null): ?>
<section class="mt-4" aria-label="Resumen de tu ámbito autorizado"><div class="row g-3"><?php foreach(['pacientes'=>'Pacientes','medicos'=>'Médicos','especialidades'=>'Especialidades','citas'=>'Citas en el periodo'] as $key=>$label): ?><div class="col-6 col-lg-3"><article class="patient-card report-summary"><span class="eyebrow text-secondary"><?= $escape($label) ?></span><strong class="d-block display-6 mt-2"><?= $escape((string)$overview['summary'][$key]) ?></strong><small class="text-secondary"><?= $key==='citas'?'Próximos diez días hábiles':$escape($overview['scope_label']) ?></small></article></div><?php endforeach; ?></div></section>
<section class="patient-card mt-4"><div class="schedule-card-heading"><h2 class="h5 mb-0">Próximas citas</h2><a href="<?= $escape(\Clinica\Middleware\CitaAccess::base($user)) ?>">Ver agenda completa →</a></div><?php if(!$upcoming): ?><p class="report-zero">No tienes próximas citas en este periodo.</p><?php else: ?><div class="table-responsive"><table class="table patient-table mb-0"><thead><tr><th>Cita</th><th>Fecha y hora</th><th>Médico</th><th>Estado</th></tr></thead><tbody><?php foreach($upcoming as $appointment): ?><tr><td><a href="<?= $escape(\Clinica\Middleware\CitaAccess::base($user)) ?>/detalle?id=<?= (int)$appointment['id_cita'] ?>"><?= $escape($appointment['codigo_cita']) ?></a></td><td><?= $escape($appointment['fecha'].' '.substr($appointment['hora_inicio'],0,5)) ?></td><td><?= $escape($appointment['medico_nombre']) ?></td><td><?= $escape($appointment['estado']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="patient-card mt-4"><div class="schedule-card-heading"><h2 class="h5 mb-0">Estados de las citas del periodo</h2></div><div class="d-flex flex-wrap gap-3 p-3"><?php $states=array_fill_keys(\Clinica\Services\CitaFilters::STATES,0);foreach($overview['appointments'] as $row){++$states[$row['estado']];}foreach($states as $state=>$count): ?><span class="status-chip is-inactive"><?= $escape(ucfirst($state)) ?>: <strong><?= $count ?></strong></span><?php endforeach; ?></div></section>
<?php endif; ?>
<?php if(\Clinica\Middleware\PaymentAccess::view($user)): ?><section class="card p-4 mt-4"><h2 class="h5">Pagos y reservas provisionales</h2><p>Consulta los estados, vencimientos y comprobantes de demostración en tu ámbito autorizado.</p><a class="btn btn-clinic align-self-start" href="<?= $user['role']==='Paciente'?'/mis-pagos':'/pagos' ?>">Consultar pagos y reservas →</a></section><?php endif; ?>
<?php if($user['role']==='Paciente'): ?><section class="card p-4 mt-4"><h2 class="h5">Mi perfil y notificaciones</h2><div class="d-flex flex-wrap gap-2"><a href="/mi-perfil" class="btn btn-clinic">Mi perfil</a><a href="/mis-notificaciones" class="btn btn-outline-secondary">Mis notificaciones</a><a href="/mis-citas/reservar" class="btn btn-outline-secondary">Reservar cita</a></div></section><?php endif; ?>
